Object.assign(WD_CONF,{
p111_circum:{t:'circum- শব্দ তিনটি: কোনটা কী?',tip:'তিনটিতেই circum = চারদিকে। circuitous → পথ ঘুরিয়ে লম্বা করা। circumspect → চারদিক দেখে সাবধানে চলা (সতর্ক)। circumvent → বাধা বা নিয়মের পাশ কাটিয়ে যাওয়া।',
 w:[{w:'circuitous',u:'পথ বা কথা সোজা নয়, ঘুরিয়ে (route, way, explanation)',ex:'We reached the village by a circuitous route.'},
    {w:'circumspect',u:'মানুষ সতর্ক, ঝুঁকি নিতে চায় না',ex:'She is circumspect in choosing her friends.'},
    {w:'circumvent',u:'নিয়ম, আইন বা বাধা কৌশলে এড়িয়ে যাওয়া (verb)',ex:'They found a way to circumvent the tax law.'}],
 q:[['Smugglers try to ___ customs checks at the border.','circumvent'],['A wise investor is ___ and studies a company before buying its shares.','circumspect'],['The river takes a ___ course through the plains before reaching the sea.','circuitous']]},
p111_coerce:{t:'জোর করে নাকি মিষ্টি কথায়?',tip:'coerce → হুমকি বা বলপ্রয়োগে বাধ্য করা। compel → (আইন, পরিস্থিতি বা কেউ) বাধ্য করা; সাধারণ শব্দ। cajole → তোষামোদ আর মিষ্টি কথায় রাজি করানো।',
 w:[{w:'coerce',u:'ভয় দেখিয়ে, চাপ দিয়ে করানো',ex:'The gang coerced shopkeepers into paying money.'},
    {w:'compel',u:'বাধ্য করা (আইন, অসুস্থতা, পরিস্থিতি)',ex:'Illness compelled him to leave his job.'},
    {w:'cajole',u:'আদর-আবদার, মিষ্টি কথায় রাজি করানো',ex:'She cajoled her father into buying her a new phone.'}],
 q:[['The kidnappers tried to ___ him with threats against his family.','coerce'],['With sweet words and smiles, the child tried to ___ his mother into buying ice cream.','cajole'],['The law will ___ all factories to treat their waste water.','compel']]},
p111_complacent:{t:'complacent নাকি complaisant?',tip:'complacent → নিজের ওপর খুশি হয়ে গা-ছাড়া (আত্মতুষ্ট)। complaisant → অন্যকে খুশি করতে সহজে রাজি হয়ে যায় (বাধ্য, নমনীয়)।',
 w:[{w:'complacent',u:'আত্মতুষ্ট, তাই অসতর্ক',ex:'We cannot be complacent about road safety.'},
    {w:'complaisant',u:'অন্যের ইচ্ছায় সহজে রাজি, বাধ্য',ex:'The complaisant clerk agreed to every request.'}],
 q:[['A ___ host happily agrees to whatever the guests want.','complaisant'],['Do not grow ___ just because you passed the preliminary test.','complacent']]},
p111_brief:{t:'সংক্ষিপ্ত: প্রশংসা নাকি রূঢ়তা?',tip:'concise ও succinct → ছোট কিন্তু সম্পূর্ণ, প্রশংসার শব্দ (লেখা, সারাংশ)। terse → এত ছোট যে রূঢ় / রুক্ষ শোনায়। laconic → মানুষটাই স্বভাবে কম কথা বলে।',
 w:[{w:'concise',u:'লেখা বা বক্তব্য অল্প কথায় পূর্ণাঙ্গ',ex:'Give a concise answer to each question.'},
    {w:'succinct',u:'ছোট ও একেবারে মূল কথায় (প্রায় concise-এর মতো)',ex:'His succinct speech lasted only two minutes.'},
    {w:'terse',u:'খুব ছোট এবং রুক্ষ, যেন বিরক্ত',ex:'She gave a terse "No" and shut the door.'},
    {w:'laconic',u:'স্বভাবে স্বল্পভাষী মানুষ',ex:'My laconic uncle answers most questions with a nod.'}],
 q:[['The angry officer gave a ___ reply: "Not now."','terse'],['My grandfather was a ___ man who rarely said more than a few words.','laconic'],['Write a ___ précis of the passage, about one-third of its length.','concise']]},
p111_condone:{t:'condone, condemn নাকি condole?',tip:'condone → অন্যায় দেখেও মেনে নেওয়া / প্রশ্রয় দেওয়া। condemn → তীব্র নিন্দা করা (প্রায় উল্টো)। condole → শোকে সমবেদনা জানানো (condole with someone)।',
 w:[{w:'condone',u:'অন্যায় মেনে নেওয়া, প্রশ্রয় দেওয়া',ex:'We cannot condone cheating in exams.'},
    {w:'condemn',u:'প্রকাশ্যে তীব্র নিন্দা করা',ex:'Everyone condemned the attack on the school.'},
    {w:'condole',u:'শোকাহত কাউকে সমবেদনা জানানো',ex:'Friends came to condole with the family.'}],
 q:[['The whole country rushed to ___ the brutal attack.','condemn'],['By staying silent, the principal seemed to ___ the students\' bad behaviour.','condone'],['We visited their house to ___ with them on the death of their father.','condole']]},
p111_congenial:{t:'congenial, congenital নাকি genial?',tip:'congenial → মনের মতো, অনুকূল (মানুষ, পরিবেশ)। congenital → জন্মগত (রোগ, ত্রুটি)। genial → হাসিখুশি, বন্ধুসুলভ (মানুষ)।',
 w:[{w:'congenial',u:'মনের মতো, স্বভাবে মেলে এমন; অনুকূল পরিবেশ',ex:'He found the village a congenial place to write.'},
    {w:'congenital',u:'জন্ম থেকেই আছে (রোগ, ত্রুটি)',ex:'The child has a congenital heart problem.'},
    {w:'genial',u:'হাসিখুশি, অমায়িক মানুষ',ex:'Our genial host welcomed everyone with a smile.'}],
 q:[['The baby was born with a ___ hearing defect.','congenital'],['I hope to work in a ___ office with like-minded people.','congenial'],['The ___ old shopkeeper always greets children with a smile.','genial']]},
p111_dispute:{t:'controversy, controversial নাকি contentious?',tip:'controversy → বিশেষ্য: বিতর্ক নিজেই। controversial → বিশেষণ: যে বিষয় / মানুষ নিয়ে বিতর্ক চলে। contentious → বিতর্ক জাগাতে পারে এমন বিষয়, আবার ঝগড়াটে মানুষও।',
 w:[{w:'controversy',u:'বিতর্ক (noun)',ex:'The decision led to a long controversy.'},
    {w:'controversial',u:'বিতর্কিত বিষয় বা ব্যক্তি (adjective)',ex:'The film\'s ending was controversial.'},
    {w:'contentious',u:'বিরোধ সৃষ্টিকারী বিষয়; ঝগড়াটে স্বভাবের মানুষ',ex:'Water sharing is a contentious topic.'}],
 q:[['The new law has caused a lot of ___ in the media.','controversy'],['He is a ___ person who starts an argument in every discussion.','contentious'],['The minister made a ___ remark, and people are still debating it.','controversial']]},
p111_corroborate:{t:'corroborate নাকি collaborate?',tip:'corroborate → প্রমাণ দিয়ে কোনো কথা সত্য বলে নিশ্চিত করা। collaborate → একসাথে কাজ করা (কখনো শত্রুর সঙ্গে হাত মেলানো)।',
 w:[{w:'corroborate',u:'সাক্ষ্য / প্রমাণ দিয়ে সত্যতা নিশ্চিত করা',ex:'The test results corroborate her theory.'},
    {w:'collaborate',u:'একসাথে কাজ করা, যৌথভাবে করা',ex:'The two universities collaborated on the project.'}],
 q:[['Scientists from five countries will ___ on the research.','collaborate'],['Fingerprints on the knife may ___ the witness\'s statement.','corroborate']]},
p111_covert:{t:'covert নাকি overt?',tip:'দুটো একেবারে উল্টো। covert = ঢাকা (cover), গোপন। overt = খোলাখুলি, প্রকাশ্য।',
 w:[{w:'covert',u:'গোপন, লুকানো',ex:'The spy sent covert reports to his country.'},
    {w:'overt',u:'প্রকাশ্য, সবাই দেখতে পায়',ex:'There was overt anger in his voice.'}],
 q:[['There was ___ hostility between the two groups; everyone could see it.','overt'],['The spy\'s ___ activities were discovered only years later.','covert']]},
p111_secret:{t:'গোপন: কোন ধরনের গোপন?',tip:'clandestine → গোপন এবং প্রায়ই অবৈধ / নিষিদ্ধ (meeting, trade)। covert → সরকারি বা সামরিক গোপন কার্যক্রম (operation)। surreptitious → চুপিসারে, কেউ যেন টের না পায়। furtive → অপরাধী ভঙ্গিতে লুকিয়ে, ভয়ে ভয়ে (glance, look)।',
 w:[{w:'clandestine',u:'গোপন ও অবৈধ / নিষিদ্ধ কাজ',ex:'They ran a clandestine gold trade.'},
    {w:'covert',u:'রাষ্ট্র, সেনা, গোয়েন্দার গোপন কাজ',ex:'It was a covert military operation.'},
    {w:'surreptitious',u:'চুপিসারে, অন্যের অজান্তে',ex:'He made a surreptitious recording of the meeting.'},
    {w:'furtive',u:'ধরা পড়ার ভয়ে লুকিয়ে-চুরিয়ে (চাহনি, ভঙ্গি)',ex:'The thief gave a furtive look around the room.'}],
 q:[['He cast a ___ glance at the door, as if afraid of being caught.','furtive'],['The intelligence agency ran a ___ operation in enemy territory.','covert'],['The drug gang held ___ meetings in an old warehouse.','clandestine']]},
p111_credulous:{t:'credulous, credible নাকি creditable?',tip:'credulous → মানুষ, যে সহজেই বিশ্বাস করে ফেলে। credible → কথা, সাক্ষী, উৎস যা বিশ্বাসযোগ্য। creditable → প্রশংসার যোগ্য (performance, effort)।',
 w:[{w:'credulous',u:'অতিবিশ্বাসী, সহজে ঠকে যায় এমন মানুষ',ex:'Credulous buyers believed the fake advertisement.'},
    {w:'credible',u:'বিশ্বাসযোগ্য (তথ্য, সাক্ষী, হুমকি)',ex:'We need credible evidence before we act.'},
    {w:'creditable',u:'প্রশংসনীয়, সুনাম আনে এমন',ex:'The team gave a creditable performance.'}],
 q:[['The police found the witness ___ and accepted her statement.','credible'],['The team gave a ___ performance despite losing the final.','creditable'],['Many ___ people fall for online lottery scams.','credulous']]},
p111_cursory:{t:'cursory নাকি perfunctory?',tip:'cursory → তাড়াহুড়োয় ভাসা-ভাসা (দ্রুততাই মূল কথা: glance, look, reading)। perfunctory → মন না দিয়ে শুধু দায়সারাভাবে নিয়ম রক্ষা (আগ্রহের অভাবই মূল কথা: smile, nod, duty)।',
 w:[{w:'cursory',u:'দ্রুত, ভাসা-ভাসা দেখা বা পড়া',ex:'He gave the letter a cursory reading.'},
    {w:'perfunctory',u:'দায়সারা, আন্তরিকতাহীন',ex:'She gave a perfunctory smile and turned away.'}],
 q:[['The tired clerk gave a ___ nod, just to show he was doing his duty.','perfunctory'],['I had time for only a ___ look at the newspaper before leaving.','cursory']]},
p111_scold:{t:'তিরস্কার করা: কোনটা কোথায়?',tip:'castigate → কঠোর ভাষায় তীব্র সমালোচনা (প্রায়ই প্রকাশ্যে, লেখায়)। censure → আনুষ্ঠানিক / সরকারিভাবে নিন্দা (সংসদ, কমিটি)। reprimand → উর্ধ্বতনের আনুষ্ঠানিক তিরস্কার (অফিসে)। chastise → বকা বা শাস্তি দিয়ে শোধরানো।',
 w:[{w:'castigate',u:'কড়া ভাষায় তীব্র সমালোচনা',ex:'The press castigated the company for polluting the river.'},
    {w:'censure',u:'আনুষ্ঠানিক নিন্দা (সংসদ, বোর্ড)',ex:'Parliament censured the minister.'},
    {w:'reprimand',u:'অফিসে উর্ধ্বতনের আনুষ্ঠানিক বকা',ex:'The officer was reprimanded for being late.'},
    {w:'chastise',u:'বকা / শাস্তি দিয়ে শোধরানো',ex:'The mother chastised her son for lying.'}],
 q:[['Parliament passed a motion to ___ the minister.','censure'],['Critics were quick to ___ the film in harsh reviews.','castigate'],['The manager had to ___ the clerk for coming late again.','reprimand']]},
p111_censor:{t:'censure নাকি censor?',tip:'censor → বই, সিনেমা, খবর থেকে আপত্তিকর অংশ কেটে বাদ দেওয়া / নিষিদ্ধ করা। censure → কাউকে কঠোরভাবে / আনুষ্ঠানিকভাবে নিন্দা করা।',
 w:[{w:'censor',u:'আপত্তিকর অংশ কেটে বাদ দেওয়া; যে এই কাজ করে',ex:'The government censored the news report.'},
    {w:'censure',u:'আনুষ্ঠানিক নিন্দা করা',ex:'The doctor was censured by the medical council.'}],
 q:[['The board will ___ the violent scenes before the film is released.','censor'],['The committee voted to ___ the member for his rude behaviour.','censure']]},
p111_caustic:{t:'কটু কথা: caustic, sarcastic নাকি sardonic?',tip:'caustic → এত কটু যে পোড়ায়, আঘাত দেয় (রাসায়নিক অর্থেও দাহক)। sarcastic → উল্টো কথা বলে বিদ্রূপ ("দারুণ কাজ!" যখন কাজ খারাপ)। sardonic → তাচ্ছিল্যভরা ঠাণ্ডা বাঁকা হাসি / ঠাট্টা। acerbic → ঝাঁঝালো, তীক্ষ্ণ সমালোচনা।',
 w:[{w:'caustic',u:'পোড়ায় এমন কটু; রাসায়নিকভাবে দাহক',ex:'His caustic review hurt the young writer.'},
    {w:'sarcastic',u:'উল্টো অর্থে বলা বিদ্রূপ',ex:'"What a lovely day," she said in a sarcastic voice as it poured.'},
    {w:'sardonic',u:'তাচ্ছিল্যের বাঁকা হাসি বা মন্তব্য',ex:'He gave a sardonic laugh at our plan.'},
    {w:'acerbic',u:'ঝাঁঝালো, তীক্ষ্ণ বুদ্ধির সমালোচনা',ex:'The columnist is known for her acerbic wit.'}],
 q:[['When I broke the glass, he said "Well done!" in a ___ voice.','sarcastic'],['Some industrial chemicals are ___ enough to burn the skin.','caustic'],['He gave a ___ smile, as if he found our worries foolish.','sardonic']]},
p111_famous:{t:'বিখ্যাত নাকি কুখ্যাত?',tip:'celebrated → ভালো কাজের জন্য সবার প্রিয়, বিখ্যাত। eminent → নিজের পেশা / ক্ষেত্রে বিশিষ্ট ও সম্মানিত (eminent scientist, lawyer)। notorious → খারাপ কাজের জন্য কুখ্যাত।',
 w:[{w:'celebrated',u:'বিখ্যাত, প্রশংসিত (মানুষ, স্থান, কাজ)',ex:'Sundarbans is celebrated for its Royal Bengal tigers.'},
    {w:'eminent',u:'নিজের ক্ষেত্রে বিশিষ্ট, গণ্যমান্য',ex:'An eminent economist chaired the meeting.'},
    {w:'notorious',u:'খারাপ কাজের জন্য কুখ্যাত',ex:'The road is notorious for accidents.'}],
 q:[['The police finally arrested the ___ smuggler.','notorious'],['Cox\'s Bazar is ___ for its long sandy beach.','celebrated'],['The university invited an ___ physicist to give the lecture.','eminent']]},
p111_lack:{t:'অভাব: dearth, paucity নাকি scarcity?',tip:'তিনটিই অভাব। dearth → কোনো কিছুর ঘাটতি (dearth of teachers / food)। paucity → সংখ্যা বা পরিমাণে খুব কম, আনুষ্ঠানিক (paucity of evidence / data)। scarcity → চাহিদার তুলনায় যোগান কম (পানি, খাদ্য; অর্থনীতিতে বেশি)।',
 w:[{w:'dearth',u:'ঘাটতি, অভাব (a dearth of)',ex:'There is a dearth of good books in the library.'},
    {w:'paucity',u:'খুবই অল্প পরিমাণ (formal: evidence, data, information)',ex:'The paucity of data made the study difficult.'},
    {w:'scarcity',u:'চাহিদার তুলনায় যোগানের অভাব (water, food, resources)',ex:'Water scarcity is rising in many countries.'}],
 q:[['The case was dismissed owing to a ___ of evidence.','paucity'],['Water ___ is a growing problem in the Barind region in summer.','scarcity'],['There is a ___ of qualified doctors in remote areas.','dearth']]}
});

